def _C3lookup(k):
    return _C3.T.get(k) or _C3B.T.get(k) or _C3C.T.get(k) or _C3D.T.get(k) or _C3E.T.get(k) or _C3F.T.get(k)

class _H1:
    """Snapshot pool routing + shared param extraction. Call via _H1.<name>(...)."""

    def _wrap(token, chain_id):
        if str(token).lower() in _C.NATIVE:
            return _C.WETH.get(int(chain_id or 0), token)
        return token

    def _v3_zfo(sp, liq, aaf):
        den = liq * _C.Q96 + aaf * sp
        if den <= 0:
            return 0
        delta = aaf * sp * sp // den
        if delta > sp // 100:
            return 0
        return liq * delta // _C.Q96

    def _v3_ofz(sp, liq, aaf):
        delta = aaf * _C.Q96 // liq
        if delta > sp // 100:
            return 0
        new_sp = sp + delta
        if new_sp <= 0:
            return 0
        return liq * _C.Q96 * delta // (sp * new_sp)

    def _v3_out(sqrt_price_x96, liquidity, amount_in, zero_for_one, fee_ppm):
        if liquidity <= 0 or amount_in <= 0 or sqrt_price_x96 <= 0:
            return 0
        aaf = amount_in * (1000000 - fee_ppm) // 1000000
        if aaf <= 0:
            return 0
        if zero_for_one:
            out = _H1._v3_zfo(sqrt_price_x96, liquidity, aaf)
        else:
            out = _H1._v3_ofz(sqrt_price_x96, liquidity, aaf)
        return max(0, out)

    def _pair_out(pool, x, y, amt):
        t0 = str(pool.get('token0', '') or '').lower()
        t1 = str(pool.get('token1', '') or '').lower()
        if t0 == x and t1 == y:
            zfo = True
        elif t0 == y and t1 == x:
            zfo = False
        else:
            return None
        fee = int(pool.get('fee', 3000) or 3000)
        out = _H1._v3_out(int(pool.get('sqrtPriceX96', 0) or 0), int(pool.get('liquidity', 0) or 0), amt, zfo, fee)
        return (out, fee)

    def _best_direct(pool_states, tin, tout, amt):
        x, y = (tin.lower(), tout.lower())
        best = None
        for addr, pool in pool_states.items():
            r = _H1._pair_out(pool, x, y, amt)
            if r is None:
                continue
            out, fee = r
            if out > 0 and (best is None or out > best[0]):
                best = (out, addr, pool, fee)
        return best

    def _hop(d):
        return {'pool_addr': d[1], 'pool_state': d[2], 'fee': d[3]}

    def _route_2hop(pool_states, tin, tout, amt, mid, result):
        m = str(mid).lower()
        if m == tin.lower() or m == tout.lower():
            return result
        h1 = _H1._best_direct(pool_states, tin, mid, amt)
        if not h1:
            return result
        h2 = _H1._best_direct(pool_states, mid, tout, h1[0])
        if not h2:
            return result
        if result is None or h2[0] > result[0]:
            return (h2[0], f'2hop:{mid[:8]}', [_H1._hop(h1), _H1._hop(h2)])
        return result

    def _best_route(pool_states, tin, tout, amt, mids):
        result = None
        d = _H1._best_direct(pool_states, tin, tout, amt)
        if d:
            result = (d[0], 'direct', [_H1._hop(d)])
        for mid in mids or []:
            result = _H1._route_2hop(pool_states, tin, tout, amt, mid, result)
        return result

    def _dex_subset(pool_states, dex):
        if dex == 'uniswap_v3':
            return {a: p for a, p in pool_states.items() if (p.get('dex') or 'uniswap_v3') == 'uniswap_v3'}
        return {a: p for a, p in pool_states.items() if p.get('dex') == dex}

    def _subset_route(pool_states, tin, tout, amt, mids):
        cands = []
        for dex in ('uniswap_v3', 'aerodrome_slipstream'):
            subset = _H1._dex_subset(pool_states, dex)
            if not subset:
                continue
            r = _H1._best_route(subset, tin, tout, amt, mids)
            if r is not None:
                cands.append(r)
        if cands:
            return max(cands, key=lambda r: r[0])
        d = _H1._best_direct(pool_states, tin, tout, amt)
        if d:
            return (d[0], 'direct', [_H1._hop(d)])
        return None

    def _swap_raw(sol, intent, state):
        params = sol._normalized_swap_params(intent, state)
        tin = str(params.get('input_token', '') or '')
        tout = str(params.get('output_token', '') or '')
        amt = int(params.get('input_amount', 0) or 0)
        try:
            amt = sol._effective_swap_amount(sol._fee_params(state, params), tin, amt)
        except Exception:
            pass
        return (tin, tout, amt)

    def _swap_fields(sol, intent, state, snapshot):
        tin, tout, amt = _H1._swap_raw(sol, intent, state)
        if tin.startswith('eip155:'):
            tin = tin.split(':')[-1]
        if tout.startswith('eip155:'):
            tout = tout.split(':')[-1]
        cid = int(getattr(state, 'chain_id', 0) or (getattr(snapshot, 'chain_id', 0) if snapshot else 0) or 0)
        if not tin or not tout or amt <= 0:
            return None
        return (tin, tout, amt, cid)

    def _quote_from_route(r, tin, tout):
        from minotaur_subnet.shared.types import QuoteResult
        if r and r[0] > 0:
            return QuoteResult(estimated_output=str(r[0]), route_summary=f'{tin[:8]}..->{tout[:8]}.. {r[1]}', gas_estimate=450000, metadata={'data_source': 'offline-fixed'})
        return None
_FEES3 = ((3000, 3000, 3000), (500, 500, 500), (3000, 500, 3000), (500, 3000, 500))

class _H2:
    """Live multicall routing (UniV3 / Aerodrome Slipstream / V2 forks) + candidate builders."""

    def _addr(a):
        return bytes.fromhex(a[2:].rjust(40, '0'))

    def _single_cd(tin, tout, amt, fee):
        return _C.SEL_SINGLE + _enc(['(address,address,uint256,uint24,uint160)'], [(tin, tout, amt, fee, 0)])

    def _path_cd(tokens, fees, amt):
        b = b''
        for i, t in enumerate(tokens):
            b += _H2._addr(t)
            if i < len(fees):
                b += int(fees[i]).to_bytes(3, 'big')
        return _C.SEL_PATH + _enc(['bytes', 'uint256'], [b, amt])

    def _run_mc_list(w3, subcalls):
        agg = _C.SEL_AGG3 + _enc(['(address,bool,bytes)[]'], [subcalls])
        ret = w3.eth.call({'to': w3.to_checksum_address(_C.MC3), 'data': '0x' + agg.hex()})
        results, = _dec(['(bool,bytes)[]'], ret)
        outs = []
        for ok, data in results:
            outs.append(_H2._u256(ok, data))
        return outs

    def _u256(ok, data):
        if ok and data and (len(data) >= 32):
            try:
                return _dec(['uint256'], data[:32])[0]
            except Exception:
                return 0
        return 0

    def _agg_call(w3, subs):
        data = _C.SEL_AGG3 + _enc(['(address,bool,bytes)[]'], [subs])
        r = w3.eth.call({'to': w3.to_checksum_address(_C.MC3), 'data': '0x' + data.hex()})
        res, = _dec(['(bool,bytes)[]'], r)
        return res

    def _fr_direct(w3, q, tin, tout, amt):
        best = None
        tiers = (100, 500, 3000, 10000)
        try:
            outs = _H2._run_mc_list(w3, [(q, True, _H2._single_cd(tin, tout, amt, f)) for f in tiers])
            for f, o in zip(tiers, outs):
                if o > 0 and (best is None or o > best['out']):
                    best = {'kind': 'direct', 'fee': f, 'out': o}
        except Exception:
            pass
        return best

    def _combos(kind):
        if kind == 's':
            return [(500, 100), (3000, 100), (100, 500), (100, 3000)]
        return [(500, 500), (3000, 3000), (500, 3000), (3000, 500)]

    def _hub_best(w3, q, kind, path, amt, best):
        combos = _H2._combos(kind)
        try:
            outs = _H2._run_mc_list(w3, [(q, True, _H2._path_cd(path, [f1, f2], amt)) for f1, f2 in combos])
            for (f1, f2), o in zip(combos, outs):
                if o > 0 and (best is None or o > best['out']):
                    best = {'kind': '2hop', 'hub': path[1], 'f1': f1, 'f2': f2, 'out': o}
        except Exception:
            pass
        return best

    def _fr_hubs(w3, q, cid, tin, tout, amt, best):
        for hub, kind in _C2.HUBS.get(cid, []):
            if not hub or hub.lower() in (tin.lower(), tout.lower()):
                continue
            best = _H2._hub_best(w3, q, kind, [tin, hub, tout], amt, best)
        return best

    def _hub2_best(w3, q, path4, amt, best):
        try:
            outs = _H2._run_mc_list(w3, [(q, True, _H2._path_cd(path4, list(fs), amt)) for fs in _FEES3])
            for fs, o in zip(_FEES3, outs):
                if o > 0 and (best is None or o > best['out']):
                    best = {'kind': '3hop', 'path': list(path4), 'fees': list(fs), 'out': o}
        except Exception:
            pass
        return best

    def _fr_hubs3(w3, q, cid, tin, tout, amt, best):
        hubs = [h for h, _ in _C2.HUBS.get(cid, [])][:3]
        tl, ol = (tin.lower(), tout.lower())
        for i in range(min(2, len(hubs))):
            for j in range(len(hubs)):
                h1, h2 = (hubs[i], hubs[j])
                if i == j or not h1 or (not h2):
                    continue
                if h1.lower() in (tl, ol) or h2.lower() in (tl, ol) or h1.lower() == h2.lower():
                    continue
                best = _H2._hub2_best(w3, q, [tin, h1, h2, tout], amt, best)
        return best

    def fast_route(w3, cid, tin, tout, amt):
        if cid not in _C.QUOTER or amt <= 0:
            return None
        q = _C.QUOTER[cid]
        best = _H2._fr_direct(w3, q, tin, tout, amt)
        best = _H2._fr_hubs(w3, q, cid, tin, tout, amt, best)
        best = _H2._fr_hubs3(w3, q, cid, tin, tout, amt, best)
        return best

    def _aero_sub(w3, tin, tout, amt, ts):
        return (w3.to_checksum_address(_C2.AERO_QUOTER[8453]), True, _C.AQ_SEL + _enc(['(address,address,uint256,int24,uint160)'], [(w3.to_checksum_address(tin), w3.to_checksum_address(tout), amt, ts, 0)]))

    def _aero_parse(res):
        best = None
        for ts, (ok, d) in zip(_C2.AERO_TICKS, res):
            out = _H2._u256(ok, d)
            if out > 0 and (best is None or out > best['out']):
                best = {'ts': ts, 'out': out}
        return best

    def aero_route(w3, cid, tin, tout, amt):
        if cid not in _C2.AERO_QUOTER or amt <= 0:
            return None
        try:
            res = _H2._agg_call(w3, [_H2._aero_sub(w3, tin, tout, amt, ts) for ts in _C2.AERO_TICKS])
        except Exception:
            return None
        return _H2._aero_parse(res)

    def _v2_aero_sub(ck, tin, tout, amt, stable):
        return (ck(_C2.AERO_V2_R), True, _C.AERO_SEL + _enc(['uint256', '(address,address,bool,address)[]'], [amt, [(ck(tin), ck(tout), stable, ck(_C2.AERO_V2_F))]]))

    def _v2_subs(w3, tin, tout, amt):
        ck = w3.to_checksum_address
        subs = [_H2._v2_aero_sub(ck, tin, tout, amt, s) for s in (False, True)]
        meta = [('aerodrome_v2', False), ('aerodrome_v2', True)]
        subs.append((ck(_C2.UNIV2_R), True, _C.UNIV2_SEL + _enc(['uint256', 'address[]'], [amt, [ck(tin), ck(tout)]])))
        meta.append(('uniswap_v2', None))
        return (subs, meta)

    def _v2_parse(meta, res):
        best = None
        for (venue, stable), (ok, d) in zip(meta, res):
            out = 0
            if ok and d:
                try:
                    amounts = _dec(['uint256[]'], d)[0]
                    out = int(amounts[-1]) if amounts else 0
                except Exception:
                    out = 0
            if out > 0 and (best is None or out > best['out']):
                best = {'venue': venue, 'stable': stable, 'out': out}
        return best

    def v2_route(w3, cid, tin, tout, amt):
        if cid != 8453 or amt <= 0:
            return None
        subs, meta = _H2._v2_subs(w3, tin, tout, amt)
        try:
            res = _H2._agg_call(w3, subs)
        except Exception:
            return None
        return _H2._v2_parse(meta, res)

    def _v2_hub_subs(ck, tin, tout, amt, cand):
        return [(ck(_C2.UNIV2_R), True, _C.UNIV2_SEL + _enc(['uint256', 'address[]'], [amt, [ck(tin), ck(h), ck(tout)]])) for h in cand]

    def _v2_hub_pick(cand, res):
        best_h, best_o = (None, 0)
        for h, (ok, d) in zip(cand, res):
            if ok and d:
                try:
                    amounts = _dec(['uint256[]'], d)[0]
                    o = int(amounts[-1]) if amounts else 0
                    if o > best_o:
                        best_h, best_o = (h, o)
                except Exception:
                    pass
        return (best_h, best_o)

    def _v2_hub_best(w3, tin, tout, amt, hubs):
        ck = w3.to_checksum_address
        cand = [h for h in hubs if str(h).lower() not in (str(tin).lower(), str(tout).lower())]
        try:
            res = _H2._agg_call(w3, _H2._v2_hub_subs(ck, tin, tout, amt, cand))
        except Exception:
            return (None, 0)
        return _H2._v2_hub_pick(cand, res)

    def _pancake_best(w3, tin, tout, amt, hubs):
        ck = w3.to_checksum_address
        paths = [[tin, tout]] + [[tin, h, tout] for h in hubs if str(h).lower() not in (str(tin).lower(), str(tout).lower())]
        subs = [(ck(_C2.PANCAKE_R), True, _C.UNIV2_SEL + _enc(['uint256', 'address[]'], [amt, [ck(x) for x in p]])) for p in paths]
        try:
            res = _H2._agg_call(w3, subs)
        except Exception:
            return (None, 0)
        return _H2._paths_pick(paths, res)

    def _paths_pick(paths, res):
        best_p, best_o = (None, 0)
        for p, (ok, d) in zip(paths, res):
            if ok and d:
                try:
                    a = _dec(['uint256[]'], d)[0]
                    o = int(a[-1]) if a else 0
                    if o > best_o:
                        best_p, best_o = (p, o)
                except Exception:
                    pass
        return (best_p, best_o)

    def _v2_direct_out(w3, tin, tout, amt):
        ck = w3.to_checksum_address
        try:
            r = w3.eth.call({'to': ck(_C2.UNIV2_R), 'data': '0x' + (_C.UNIV2_SEL + _enc(['uint256', 'address[]'], [amt, [ck(tin), ck(tout)]])).hex()})
            a = _dec(['uint256[]'], r)[0]
            return int(a[-1]) if a else 0
        except Exception:
            return 0

    def _v2_hub_out(w3, tin, hub, tout, amt):
        ck = w3.to_checksum_address
        if str(hub).lower() in (str(tin).lower(), str(tout).lower()):
            return 0
        try:
            data = _C.UNIV2_SEL + _enc(['uint256', 'address[]'], [amt, [ck(tin), ck(hub), ck(tout)]])
            r = w3.eth.call({'to': ck(_C2.UNIV2_R), 'data': '0x' + data.hex()})
            amounts = _dec(['uint256[]'], r)[0]
            return int(amounts[-1]) if amounts else 0
        except Exception:
            return 0

    def _cand_fast(rt, wtin, wtout, amt):
        if not rt or rt.get('out', 0) <= 0:
            return None
        if rt['kind'] == 'direct':
            return {'venue': 'uniswap_v3', 'param': rt['fee'], 'out': int(rt['out']), 'gas_est': 120000, 'gas_model': 120000, 'spend_amount': amt}
        if rt['kind'] == '3hop':
            return {'venue': 'uni_v3_path', 'param': 'path', 'tokens': list(rt['path']), 'fees': list(rt['fees']), 'out': int(rt['out']), 'gas_est': 360000, 'gas_model': 360000, 'spend_amount': amt}
        return {'venue': 'uni_v3_path', 'param': 'path', 'tokens': [wtin, rt['hub'], wtout], 'fees': [rt['f1'], rt['f2']], 'out': int(rt['out']), 'gas_est': 240000, 'gas_model': 240000, 'spend_amount': amt}

    def _cand_aero(ar, amt):
        if not ar or ar.get('out', 0) <= 0:
            return None
        return {'venue': 'aerodrome_slipstream', 'param': ar['ts'], 'out': int(ar['out']), 'gas_est': 160000, 'gas_model': 160000, 'spend_amount': amt}

    def _cand_v2(vr, wtin, wtout, amt):
        if not vr or vr.get('out', 0) <= 0:
            return None
        if vr['venue'] == 'aerodrome_v2':
            return {'venue': 'aerodrome_v2', 'routes': [(wtin, wtout, bool(vr['stable']), _C2.AERO_V2_F)], 'param': _C2.AERO_V2_F, 'out': int(vr['out']), 'gas_est': 200000, 'gas_model': 520000, 'spend_amount': amt}
        return {'venue': 'uniswap_v2', 'tokens': [wtin, wtout], 'param': 'v2', 'out': int(vr['out']), 'gas_est': 150000, 'gas_model': 300000, 'spend_amount': amt}

    def collect(w3, cid, wtin, wtout, amt):
        cands = []
        c = _H2._cand_fast(_H2.fast_route(w3, cid, wtin, wtout, amt), wtin, wtout, amt)
        if c:
            cands.append(c)
        try:
            c = _H2._cand_aero(_H2.aero_route(w3, cid, wtin, wtout, amt), amt)
            if c:
                cands.append(c)
        except Exception:
            pass
        try:
            c = _H2._cand_v2(_H2.v2_route(w3, cid, wtin, wtout, amt), wtin, wtout, amt)
            if c:
                cands.append(c)
        except Exception:
            pass
        return cands

def _out_of(x):
    """Delivered-output magnitude of a plan / route-tuple / QuoteResult, or -1 if None.
    Used to compare OUR route vs the CHAMPION's and keep whichever delivers more (fill-only-better)."""
    if x is None:
        return -1
    if isinstance(x, tuple):
        try:
            return int(x[0])
        except Exception:
            return 0
    eo = getattr(x, 'estimated_output', None)
    if eo not in (None, ''):
        try:
            return int(eo)
        except Exception:
            pass
    md = getattr(x, 'metadata', None) or {}
    for k in ('expected_output', 'output_amount', 'estimated_output', 'min_output_amount'):
        v = md.get(k)
        if v not in (None, ''):
            try:
                return int(v)
            except Exception:
                pass
    return 0
_BETTER_N, _BETTER_D = (101, 100)

def _v2parts(tin, tout, flag):
    from eth_utils import to_checksum_address as _ck
    router = _C3.S if flag[:1] == 's' else _C3.U
    hub = _C3.HUB.get(flag[1:2]) if len(flag) > 1 else None
    path = [_ck(tin), _ck(hub), _ck(tout)] if hub else [_ck(tin), _ck(tout)]
    return (router, path)

def _v2swap(amt, path, recip):
    from eth_utils import to_checksum_address as _ck
    return '0x' + (bytes.fromhex('5c11d795') + _enc(['uint256', 'uint256', 'address[]', 'address', 'uint256'], [int(amt), 0, path, _ck(recip), 9999999999])).hex()

def _fewer_hops(cheap, champ, champ_out):
    try:
        ci = getattr(cheap, 'interactions', None) or []
        pi = getattr(champ, 'interactions', None) or []
        return _out_of(cheap) >= champ_out and 0 < len(ci) < len(pi)
    except Exception:
        return False

def _pancake_plan(sol, intent, state, path, amt, out):
    """PancakeV2 swap: approve + swapExactTokensForTokensSupportingFeeOnTransferTokens on the Pancake
    router. A venue the base/champion doesn't scan (verified 103% of champion on USDC->COW)."""
    from minotaur_subnet.shared.types import Interaction, ExecutionPlan
    from common.abi_utils import encode_approve
    from eth_utils import to_checksum_address as _ck
    recip, _ = _recip_exe(sol, intent, state)
    swap = _v2swap(amt, [_ck(x) for x in path], recip)
    ix = [Interaction(target=_ck(path[0]), value='0', call_data=encode_approve(_ck(_C2.PANCAKE_R), int(amt)), chain_id=8453), Interaction(target=_ck(_C2.PANCAKE_R), value='0', call_data=swap, chain_id=8453)]
    return ExecutionPlan(intent_id=intent.app_id, interactions=ix, deadline=9999999999, nonce=state.nonce, metadata={'solver': 'pancake_v2', 'chain_id': 8453, 'expected_output': str(out)})

def _recip_exe(sol, intent, state):
    p = sol._normalized_swap_params(intent, state)
    recip = str(p.get('receiver', '') or getattr(state, 'contract_address', None) or getattr(state, 'owner', None) or '0x0000000000000000000000000000000000000001')
    return (recip, str(getattr(state, 'contract_address', None) or recip))

def _atoken_plan(sol, intent, state, uin, tout, amt, out):
    """aToken -> underlying -> tout: Aave withdraw then UniV2 swap. Champion can't route aTokens."""
    from minotaur_subnet.shared.types import Interaction, ExecutionPlan
    from common.abi_utils import encode_approve
    from eth_utils import to_checksum_address as _ck
    recip, exe = _recip_exe(sol, intent, state)
    wd = '0x' + (bytes.fromhex('69328dec') + _enc(['address', 'uint256', 'address'], [_ck(uin), int(amt), _ck(exe)])).hex()
    ix = [Interaction(target=_ck(_C2.AAVE_POOL), value='0', call_data=wd, chain_id=8453), Interaction(target=_ck(uin), value='0', call_data=encode_approve(_ck(_C2.UNIV2_R), int(amt)), chain_id=8453), Interaction(target=_ck(_C2.UNIV2_R), value='0', call_data=_v2swap(amt, [_ck(uin), _ck(tout)], recip), chain_id=8453)]
    return ExecutionPlan(intent_id=intent.app_id, interactions=ix, deadline=9999999999, nonce=state.nonce, metadata={'solver': 'atoken', 'chain_id': 8453, 'expected_output': str(out)})
_UNIV3_ROUTER = '0x2626664c2603336E57B271c5C0b26F421741e481'

def _u3_quote(w3, path_bytes, amt):
    from eth_utils import to_checksum_address as _ck
    q = _C.QUOTER.get(8453)
    if not q:
        return 0
    try:
        data = '0x' + (bytes.fromhex('cdca1753') + _enc(['bytes', 'uint256'], [path_bytes, int(amt)])).hex()
        r = w3.eth.call({'to': _ck(q), 'data': data})
        b = bytes(r)
        return int.from_bytes(b[:32], 'big') if len(b) >= 32 else 0
    except Exception:
        return 0

def _u3_route(w3, tin, tout, amt):
    hubs = ('0x4200000000000000000000000000000000000006', '0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913')

    def _p(toks, fees):
        s = toks[0].lower().replace('0x', '')
        for i, f in enumerate(fees):
            s += format(int(f), '06x') + toks[i + 1].lower().replace('0x', '')
        return bytes.fromhex(s)
    cands = [([tin, tout], [f]) for f in (100, 500, 3000, 10000)]
    for h in hubs:
        if h.lower() in (tin.lower(), tout.lower()):
            continue
        for f1 in (100, 500, 3000):
            for f2 in (100, 500, 3000):
                cands.append(([tin, h, tout], [f1, f2]))
    best = (b'', 0)
    for toks, fees in cands:
        pb = _p(toks, fees)
        o = _u3_quote(w3, pb, amt)
        if o > best[1]:
            best = (pb, o)
    return best

def _cd_withdraw(uin, amt, exe):
    from eth_utils import to_checksum_address as _ck
    return '0x' + (bytes.fromhex('69328dec') + _enc(['address', 'uint256', 'address'], [_ck(uin), int(amt), _ck(exe)])).hex()

def _cd_exactinput(path_bytes, exe, amt):
    from eth_utils import to_checksum_address as _ck
    return '0x' + (bytes.fromhex('b858183f') + _enc(['(bytes,address,uint256,uint256)'], [(path_bytes, _ck(exe), int(amt), 0)])).hex()

def _cd_supply(uout, amt, recip):
    from eth_utils import to_checksum_address as _ck
    return '0x' + (bytes.fromhex('617ba037') + _enc(['address', 'uint256', 'address', 'uint16'], [_ck(uout), int(amt), _ck(recip), 0])).hex()

def _atoken2_plan(sol, intent, state, uin, uout, amt, path_bytes, out_q):
    """aToken -> aToken: Aave withdraw(uin) -> UniV3 swap(uin->uout, to executor) -> Aave supply(uout, to
    receiver). Structurally UNIQUE: no DEX aggregator (nor any champion fork) routes aToken->aToken — it
    needs an Aave withdraw AND supply, not a swap. Fill-only-where-champ-skips + conservative supply amount
    (90% of live quote) => min_out=0 can't revert on slippage, and champion delivers 0 => cannot regress."""
    from minotaur_subnet.shared.types import Interaction, ExecutionPlan
    from common.abi_utils import encode_approve
    from eth_utils import to_checksum_address as _ck
    recip, exe = _recip_exe(sol, intent, state)
    supply_amt = int(out_q) * 90 // 100
    if supply_amt <= 0:
        return None
    steps = [(_C2.AAVE_POOL, _cd_withdraw(uin, amt, exe)), (uin, encode_approve(_ck(_UNIV3_ROUTER), int(amt))), (_UNIV3_ROUTER, _cd_exactinput(path_bytes, exe, amt)), (uout, encode_approve(_ck(_C2.AAVE_POOL), supply_amt)), (_C2.AAVE_POOL, _cd_supply(uout, supply_amt, recip))]
    ix = [Interaction(target=_ck(t), value='0', call_data=cd, chain_id=8453) for t, cd in steps]
    return ExecutionPlan(intent_id=intent.app_id, interactions=ix, deadline=9999999999, nonce=state.nonce, metadata={'solver': 'atoken2', 'chain_id': 8453, 'expected_output': str(supply_amt)})

def _atoken_dispatch(sol, intent, state, w3, uin, tout, amt):
    uout = _C2.ATOK.get(str(tout).lower())
    if uout is not None:
        path_bytes, out_q = _u3_route(w3, uin, uout, amt)
        return _atoken2_plan(sol, intent, state, uin, uout, amt, path_bytes, out_q) if out_q > 0 else None
    out = _H2._v2_direct_out(w3, uin, tout, amt)
    return _atoken_plan(sol, intent, state, uin, tout, amt, out) if out > 0 else None

def _base_v2hub_plan(sol, intent, state, tin, tout, amt, hub, out):
    """Base UniV2 blind-spot cover: tin -> hub(VIRTUAL) -> tout via
    swapExactTokensForTokensSupportingFeeOnTransferTokens (min_out=0). Independent Virtuals-ecosystem
    coverage; reuses the proven _v2swap encoder with the Base UniV2 router."""
    from minotaur_subnet.shared.types import Interaction, ExecutionPlan
    from common.abi_utils import encode_approve
    from eth_utils import to_checksum_address as _ck
    router = _C2.UNIV2_R
    p = sol._normalized_swap_params(intent, state)
    recip = str(p.get('receiver', '') or getattr(state, 'contract_address', None) or getattr(state, 'owner', None) or '0x0000000000000000000000000000000000000001')
    swap = _v2swap(amt, [_ck(tin), _ck(hub), _ck(tout)], recip)
    ix = [Interaction(target=_ck(tin), value='0', call_data=encode_approve(_ck(router), int(amt)), chain_id=8453), Interaction(target=_ck(router), value='0', call_data=swap, chain_id=8453)]
    return ExecutionPlan(intent_id=intent.app_id, interactions=ix, deadline=9999999999, nonce=state.nonce, metadata={'solver': 'basev2hub', 'chain_id': 8453, 'expected_output': str(out)})

def _c1v2_plan(sol, intent, state, tin, tout, amt, flag):
    """Chain-1 UniV2/Sushi swap plan (approve + swapExactTokensForTokensSupportingFeeOnTransferTokens,
    min_out=0, live recipient). Mirrors the base's _chain1_build_plan structure for the V2 venues."""
    from minotaur_subnet.shared.types import Interaction, ExecutionPlan
    from common.abi_utils import encode_approve
    from eth_utils import to_checksum_address as _ck
    p = sol._normalized_swap_params(intent, state)
    recip = str(p.get('receiver', '') or getattr(state, 'contract_address', None) or getattr(state, 'owner', None) or '0x0000000000000000000000000000000000000001')
    router, path = _v2parts(tin, tout, flag)
    swap = _v2swap(amt, path, recip)
    ix = [Interaction(target=_ck(tin), value='0', call_data=encode_approve(_ck(router), int(amt)), chain_id=1), Interaction(target=_ck(router), value='0', call_data=swap, chain_id=1)]
    return ExecutionPlan(intent_id=intent.app_id, interactions=ix, deadline=9999999999, nonce=state.nonce, metadata={'solver': 'c1v2', 'chain_id': 1})

class MinerSolver(_Base):

    def metadata(self):
        base = super().metadata()
        return SolverMetadata(name=SOLVER_NAME, version=SOLVER_VERSION, author=SOLVER_AUTHOR, description='v6: factored lean multi-venue router (identical delivery, small max-region)', supported_chains=base.supported_chains, supported_intent_types=base.supported_intent_types)

    def _pick_plan(self, intent, state, snapshot, cands, wtin, wtout, amt, cid):
        for cand in sorted(cands, key=lambda c: int(c.get('out', 0)), reverse=True):
            try:
                plan = self._build_singlehop_plan(intent, state, snapshot, cand, wtin, wtout, amt, cid)
                if plan is not None and getattr(plan, 'interactions', None):
                    return plan
            except Exception:
                continue
        return None

    def _live_plan(self, intent, state, snapshot, wtin, wtout, amt, cid):
        try:
            w3 = self._get_web3(cid)
        except Exception:
            return None
        if w3 is None:
            return None
        cands = _H2.collect(w3, cid, wtin, wtout, amt)
        try:
            cands = cands + self._disc_cands(w3, cid, wtin, wtout, amt, 0, timeout=5.0)
        except Exception:
            pass
        return self._pick_plan(intent, state, snapshot, cands, wtin, wtout, amt, cid)

    def _ours_plan(self, intent, state, snapshot):
        try:
            d = _H1._swap_fields(self, intent, state, snapshot)
            if d:
                tin, tout, amt, cid = d
                wtin, wtout = (_H1._wrap(tin, cid), _H1._wrap(tout, cid))
                if wtin and wtout and (amt > 0) and (cid in _C.QUOTER):
                    return self._live_plan(intent, state, snapshot, wtin, wtout, amt, cid)
        except Exception:
            pass
        return None

    def _atoken_cover(self, intent, state, snapshot):
        try:
            d = _H1._swap_fields(self, intent, state, snapshot)
            if not d:
                return None
            tin, tout, amt, cid = d
            if cid != 8453 or amt <= 0:
                return None
            uin = _C2.ATOK.get(str(tin).lower())
            if uin is None:
                return None
            w3 = self._get_web3(cid)
            if w3 is None:
                return None
            return _atoken_dispatch(self, intent, state, w3, uin, tout, amt)
        except Exception:
            return None

    def _pancake_take(self, best, intent, state, snapshot):
        try:
            pk = self._pancake_cover(intent, state, snapshot)
            if pk is not None and _out_of(pk) * _BETTER_D > _out_of(best) * _BETTER_N:
                return pk
        except Exception:
            pass
        return None

    def _pancake_cover(self, intent, state, snapshot):
        try:
            d = _H1._swap_fields(self, intent, state, snapshot)
            if not d:
                return None
            tin, tout, amt, cid = d
            if cid != 8453 or amt <= 0:
                return None
            wtin, wtout = (_H1._wrap(tin, cid), _H1._wrap(tout, cid))
            if not (wtin and wtout):
                return None
            w3 = self._get_web3(cid)
            if w3 is None:
                return None
            path, out = _H2._pancake_best(w3, wtin, wtout, amt, _C2.COVER_HUBS)
            if not path or out <= 0:
                return None
            return _pancake_plan(self, intent, state, path, amt, out)
        except Exception:
            return None

    def _fill_cover(self, best, intent, state, snapshot):
        if _out_of(best) > 0:
            return None
        for fn in (self._atoken_cover, self._virtual_hub_plan):
            try:
                pl = fn(intent, state, snapshot)
                if pl is not None and _out_of(pl) > 0:
                    return pl
            except Exception:
                pass
        return None

    def _virtual_hub_plan(self, intent, state, snapshot):
        try:
            d = _H1._swap_fields(self, intent, state, snapshot)
            if not d:
                return None
            tin, tout, amt, cid = d
            if cid != 8453:
                return None
            wtin, wtout = (_H1._wrap(tin, cid), _H1._wrap(tout, cid))
            if not (wtin and wtout and (amt > 0)):
                return None
            w3 = self._get_web3(cid)
            if w3 is None:
                return None
            hub, out = _H2._v2_hub_best(w3, wtin, wtout, amt, _C2.COVER_HUBS)
            if hub is None or out <= 0:
                return None
            return _base_v2hub_plan(self, intent, state, wtin, wtout, amt, hub, out)
        except Exception:
            return None

    def _sweep_of(self, intent, state, snapshot):
        try:
            return self._sweep_plan(intent, state, snapshot, self._normalized_swap_params(intent, state))
        except Exception:
            return None

    def _gas_take(self, best, champ, intent, state, snapshot):
        if best is champ and champ is not None:
            try:
                return self._gas_pick(intent, state, snapshot, champ)
            except Exception:
                pass
        return None

    def generate_plan(self, intent, state, snapshot=None):
        self._snap = snapshot
        return super().generate_plan(intent, state, snapshot)

    def quote(self, intent, state, snapshot=None):
        self._snap = snapshot
        return super().quote(intent, state, snapshot)

    def _snap_hubs(self, chain_id, cap=40):
        snap = getattr(self, '_snap', None)
        ps = getattr(snap, 'pool_states', None) if snap else None
        if not ps:
            return []
        try:
            from collections import Counter
            cnt = Counter()
            for pool in ps.values():
                for k in ('token0', 'token1'):
                    t = pool.get(k)
                    if t:
                        cnt[str(t).lower()] += 1
            return [t for t, _ in cnt.most_common(cap)]
        except Exception:
            return []

    def _intermediaries_for_chain(self, chain_id):
        try:
            mids = list(super()._intermediaries_for_chain(chain_id))
        except Exception:
            mids = []
        extra = {8453: ['0xcbB7C0000aB88B473b1f5aFd9ef808440eed33Bf', '0xfde4C96c8593536E31F229EA8f37b2ADa2699bb2', '0x50c5725949A6F0c72E6C4a641F24049A917DB0Cb', '0x940181a94A35A4569E4529A3CDfB74e38FD98631', '0x0b3e328455c4059eeb9e3f84b5543f74e24e7e1b', '0x4ed4E862860beD51a9570b96d89aF5E1B0Efefed', '0xc1CBa3fCea344f92D9239c08C0568f6F2F0ee452', '0x2Ae3F1Ec7F1F5012CFEab0185bfc7aa3cf0DEc22', '0x04C0599Ae5A44757c0af6F9eC3b93da8976c150A', '0x60a3E35Cc302bFA44Cb288Bc5a4F316Fdb1adb42', '0x6Bb7a212910682DCFdbd5BCBb3e28FB4E8da10Ee'], 1: ['0xdAC17F958D2ee523a2206206994597C13D831ec7', '0x6B175474E89094C44Da98b954EedeAC495271d0F', '0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599', '0x7f39C581F595B53c5cb19bD0b3f8dA6c935E2Ca0', '0x5f98805A4E8be255a32880FDeC7F6728C6568bA0']}
        seen = {m.lower() for m in mids}
        for a in list(extra.get(int(chain_id) if chain_id else 0, [])) + self._snap_hubs(chain_id):
            if a.lower() not in seen:
                mids.append(a)
                seen.add(a.lower())
        return mids

    def _score_aware_singlehop(self, intent, state, snapshot, base_plan):
        try:
            champ = super()._score_aware_singlehop(intent, state, snapshot, base_plan)
        except Exception:
            champ = None
        ours = None
        sweep = self._sweep_of(intent, state, snapshot)
        best = champ
        for cand in (ours, sweep):
            if cand is not None and _out_of(cand) > _out_of(best):
                best = cand
        pk = self._pancake_take(best, intent, state, snapshot)
        if pk is not None:
            best = pk
        fc = self._fill_cover(best, intent, state, snapshot)
        if fc is not None:
            return fc
        gp = self._gas_take(best, champ, intent, state, snapshot)
        if gp is not None:
            return gp
        return best

    def _gas_min_plan(self, intent, state, snapshot, wtin, wtout, amt, cid, champ_out):
        try:
            w3 = self._get_web3(cid)
        except Exception:
            return None
        if w3 is None:
            return None
        cands = [c for c in _H2.collect(w3, cid, wtin, wtout, amt) if int(c.get('out', 0)) >= champ_out]
        for cand in sorted(cands, key=lambda c: int(c.get('gas_est', 10 ** 9))):
            try:
                plan = self._build_singlehop_plan(intent, state, snapshot, cand, wtin, wtout, amt, cid)
                if plan is not None and getattr(plan, 'interactions', None):
                    return plan
            except Exception:
                continue
        return None

    def _gas_pick(self, intent, state, snapshot, champ):
        champ_out = _out_of(champ)
        if champ_out <= 0:
            return None
        d = _H1._swap_fields(self, intent, state, snapshot)
        if not d:
            return None
        tin, tout, amt, cid = d
        if cid != 8453:
            return None
        wtin, wtout = (_H1._wrap(tin, cid), _H1._wrap(tout, cid))
        if not (wtin and wtout and (amt > 0)):
            return None
        cheap = self._gas_min_plan(intent, state, snapshot, wtin, wtout, amt, cid, champ_out)
        if cheap is not None and _fewer_hops(cheap, champ, champ_out):
            return cheap
        return None

    def _needs_subset(self, hops):
        if len(hops) <= 1:
            return False
        try:
            dexes = {self._hop_dex(h) for h in hops}
        except Exception:
            dexes = {'uniswap_v3'}
        return len(dexes) != 1

    def _our_route(self, pool_states, token_in, token_out, amount_in, chain_id):
        ti = _H1._wrap(token_in, chain_id)
        to = _H1._wrap(token_out, chain_id)
        try:
            mids = self._intermediaries_for_chain(chain_id)
        except Exception:
            mids = []
        r = _H1._best_route(pool_states, ti, to, amount_in, mids)
        if r is None:
            return None
        if self._needs_subset(r[2]):
            return _H1._subset_route(pool_states, ti, to, amount_in, mids)
        return r

    def _find_best_executable_route(self, pool_states, token_in, token_out, amount_in, chain_id):
        try:
            champ = super()._find_best_executable_route(pool_states, token_in, token_out, amount_in, chain_id)
        except Exception:
            champ = None
        ours = None
        try:
            ours = self._our_route(pool_states, token_in, token_out, amount_in, chain_id)
        except Exception:
            ours = None
        return ours if _out_of(ours) > _out_of(champ) else champ

    def _offline_fallback_quote(self, intent, state, snapshot):
        try:
            champ = super()._offline_fallback_quote(intent, state, snapshot)
        except Exception:
            champ = None
        ours = None
        try:
            ps = getattr(snapshot, 'pool_states', None) if snapshot else None
            d = _H1._swap_fields(self, intent, state, snapshot) if ps else None
            if d:
                tin, tout, amt, cid = d
                tin, tout = (_H1._wrap(tin, cid), _H1._wrap(tout, cid))
                try:
                    mids = self._intermediaries_for_chain(cid) if cid else []
                except Exception:
                    mids = []
                ours = _H1._quote_from_route(_H1._best_route(ps, tin, tout, amt, mids), tin, tout)
        except Exception:
            ours = None
        best = ours if _out_of(ours) > _out_of(champ) else champ
        try:

            def _deliver():
                return self._score_aware_singlehop(intent, state, snapshot, None)
            plan = self._bounded_call(_deliver, timeout=8.0)
            po = _out_of(plan)
            if po > _out_of(best):
                from minotaur_subnet.shared.types import QuoteResult
                return QuoteResult(estimated_output=str(po), route_summary='deliver-consistent', gas_estimate=450000, metadata={'data_source': 'score-aware'})
        except Exception:
            pass
        return best

    def _atoken_quote(self, intent, state, snapshot):
        from minotaur_subnet.shared.types import QuoteResult
        d = _H1._swap_fields(self, intent, state, snapshot)
        if not d:
            return None
        tin, tout, amt, cid = d
        if cid != 8453 or amt <= 0:
            return None
        uin = _C2.ATOK.get(str(tin).lower())
        if uin is None:
            return None
        w3 = self._get_web3(cid)
        if w3 is None:
            return None
        uout = _C2.ATOK.get(str(tout).lower())
        if uout is not None:
            _path, out_q = _u3_route(w3, uin, uout, amt)
            supply_amt = int(out_q) * 90 // 100
            if supply_amt <= 0:
                return None
            return QuoteResult(estimated_output=str(supply_amt), route_summary='atoken2-rpc', gas_estimate=600000, metadata={'data_source': 'atoken2-rpc'})
        out = _H2._v2_direct_out(w3, uin, tout, amt)
        if out <= 0:
            return None
        return QuoteResult(estimated_output=str(out), route_summary='atoken-rpc', gas_estimate=500000, metadata={'data_source': 'atoken-rpc'})

    def _rpc_quote(self, intent, state, snapshot):
        out = 0
        for getter in (self._ours_plan, self._sweep_of):
            try:
                pl = getter(intent, state, snapshot)
            except Exception:
                pl = None
            o = _out_of(pl)
            if o > out:
                out = o
        if out <= 0:
            return None
        return QuoteResult(estimated_output=str(out), route_summary='rpc-built', gas_estimate=450000, metadata={'data_source': 'rpc-built'})

    def _disc_cands(self, w3, cid, tin, tout, amt, min_out, timeout=8.0):
        from strategies.dex_aggregator.discovery import DiscoveryEngine

        def _call(to, data):
            try:
                return w3.eth.call({'to': to, 'data': data})
            except Exception:
                return None

        def _run():
            return DiscoveryEngine(_call).discover(cid, tin.lower(), tout.lower(), amt, min_out)
        return [c for c in self._bounded_call(_run, timeout=timeout) or [] if c.get('out', 0) > 0]

    def _discover_fill(self, intent, state, snapshot, params, min_out):
        d = _H1._swap_fields(self, intent, state, snapshot)
        if not d:
            return None
        tin, tout, amt, cid = d
        if cid not in (1, 8453):
            return None
        w3 = self._get_web3(cid)
        if w3 is None:
            return None
        cands = self._disc_cands(w3, cid, tin, tout, amt, min_out)
        if not cands:
            return None
        return self._build_singlehop_plan(intent, state, snapshot, cands[0], tin, tout, amt, cid)

    def _dynamic_discovery_plan(self, intent, state, snapshot, params):
        try:
            min_out = int(params.get('min_output_amount', 0) or 0)
            if min_out > 1:
                plan = self._discover_fill(intent, state, snapshot, params, min_out)
                if plan is not None:
                    return plan
        except Exception:
            pass
        return super()._dynamic_discovery_plan(intent, state, snapshot, params)

    def _c1_dispatch(self, intent, state, tin, tout, amt, flag):
        if flag[:1] == 'v':
            return self._chain1_build_plan(intent, state, tin, int(amt), {'tokens': [tin, tout], 'fees': [int(flag[1:])]})
        return _c1v2_plan(self, intent, state, tin, tout, int(amt), flag)

    def _chain1_v2_serve(self, intent, state):
        try:
            if int(getattr(state, 'chain_id', 0) or 0) != 1:
                return None
            pr = self._mc_params(intent, state)
            if not pr:
                return None
            tin, tout, amt, _mino = pr
            if str(tin).lower() in _C.NATIVE:
                tin = _C.WETH[1]
            if str(tout).lower() in _C.NATIVE:
                tout = _C.WETH[1]
            flag = _C3lookup('1|%s|%s' % (str(tin).lower(), str(tout).lower()))
            if not flag or int(amt) <= 0:
                return None
            return self._c1_dispatch(intent, state, tin, tout, int(amt), flag)
        except Exception:
            return None

    def _chain1_baked_serve(self, intent, state, snapshot=None):
        try:
            champ = super()._chain1_baked_serve(intent, state, snapshot)
        except Exception:
            champ = None
        if getattr(champ, 'interactions', None):
            return champ
        ours = self._chain1_v2_serve(intent, state)
        return ours if ours is not None else champ
